{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (sentiment > 0.00) and model overestimates prices, especially after recent spikes.",
    "Apply upward bias correction when model underestimates prices in the presence of sustained positive sentiment, particularly in early periods of the 30-day horizon.",
    "Reduce forecast volatility when sentiment is neutral or negative (sentiment = 0.00), as models tend to overreact in absence of sentiment signals.",
    "Correct for lagged price movements: if true outcome is significantly higher than forecasted 3–5 days prior, adjust future forecasts upward by 5–15% to account for momentum.",
    "Apply mean reversion correction: if forecast is > 10% above recent 5-day average, reduce by 5–10% to align with historical volatility patterns.",
    "Avoid sharp upward corrections after large downward spikes — model tends to overcorrect, leading to overshoots in subsequent periods."
  ]
}
